package thaumcraft.research;
import static org.junit.jupiter.api.Assertions.*;
import com.mojang.serialization.JsonOps;
import com.google.gson.*;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
class CheatResearchTest {
 @Test void allEntriesStagesCategoriesAndDiscoveryPredicatesAreGranted(){var grant=CheatResearch.complete(KnowledgeState.EMPTY);var state=grant.knowledge();assertEquals(148,ResearchCatalog.ENTRIES.size());for(var e:ResearchCatalog.ENTRIES){assertTrue(ResearchCatalog.knows(state,e.key()),e.key());assertTrue(ResearchCatalog.knows(state,e.key()+"@"+e.stages().size()));assertTrue(ResearchService.parents(state,e));for(var stage:e.stages())for(var r:stage.research())assertTrue(ResearchCatalog.knows(state,r),r);for(var a:e.addenda())for(var r:a.research())assertTrue(ResearchCatalog.knows(state,r),r);}for(var c:ResearchCatalog.CATEGORIES)assertTrue(ResearchCatalog.categoryUnlocked(state,c));assertTrue(state.flags().contains("!gotthaumonomicon"));}
 @Test void existingIndependentKnowledgeAndHigherStagesArePreserved(){var old=KnowledgeState.EMPTY.stage("FIRSTSTEPS",50).stage("addon_entry",7).scan("item:minecraft:stone").craft("thaumcraft:thaumometer").flag("addon_flag").addPoints("THEORY","BASICS",35);var next=CheatResearch.complete(old).knowledge();assertEquals(old.scans(),next.scans());assertEquals(old.crafts(),next.crafts());assertEquals(old.points(),next.points());assertTrue(next.flags().contains("addon_flag"));assertEquals(50,next.stages().get("FIRSTSTEPS"));assertEquals(7,next.stages().get("addon_entry"));assertEquals(next,KnowledgeState.CODEC.parse(JsonOps.INSTANCE,KnowledgeState.CODEC.encodeStart(JsonOps.INSTANCE,next).getOrThrow()).getOrThrow());}
 @Test void repeatedUseDoesNotRepeatResearchOrWarp(){var first=CheatResearch.complete(KnowledgeState.EMPTY);assertTrue(first.permanentWarp()>0);var again=CheatResearch.complete(first.knowledge());assertEquals(first.knowledge(),again.knowledge());assertEquals(0,again.permanentWarp());assertEquals(0,again.normalWarp());}
 @Test void completedEntriesDoNotChargeTheirWarpAgain(){var full=CheatResearch.complete(KnowledgeState.EMPTY);var e=ResearchCatalog.ENTRIES.stream().filter(x->x.stages().stream().anyMatch(s->s.warp()>0)).findFirst().orElseThrow();int permanent=e.stages().stream().mapToInt(s->(s.warp()+1)/2).sum(),normal=e.stages().stream().mapToInt(s->s.warp()/2).sum();var partially=CheatResearch.complete(KnowledgeState.EMPTY.stage(e.key(),e.stages().size()+1));assertEquals(full.permanentWarp()-permanent,partially.permanentWarp());assertEquals(full.normalWarp()-normal,partially.normalWarp());}
 @Test void originalCheatIconIsOnlySelectedByTheExplicitComponent()throws Exception{var item=JsonParser.parseString(Files.readString(Path.of("src/modern/resources/assets/thaumcraft/items/thaumonomicon.json"))).getAsJsonObject().getAsJsonObject("model");assertEquals("minecraft:has_component",item.get("property").getAsString());assertEquals("thaumcraft:cheat_sheet",item.get("component").getAsString());assertEquals("thaumcraft:item/thaumonomicon_cheat",item.getAsJsonObject("on_true").get("model").getAsString());assertEquals("thaumcraft:item/thaumonomicon",item.getAsJsonObject("on_false").get("model").getAsString());assertTrue(Files.isRegularFile(Path.of("src/main/resources/assets/thaumcraft/textures/items/thaumonomicon_cheat.png")));}
}
